const articles = [
  { title: 'Midnight Visitor', content: 'It was a stormy night. I was alone in my study, organizing old things. Suddenly, the doorbell rang. Through the peephole, I saw a man in a black raincoat, his hat pulled low.\n\n"Professor Lin?" His voice was deep and hoarse.\n\nI hesitated, then opened the door. He came in, took off his raincoat, revealing a pale face.\n\n"I was your student, ten years ago," he said. "I came to return something."\n\nHe pulled an old notebook from his coat, one I had given to an excellent student.\n\n"I\'ve kept it all these years. Now it\'s time to return it to its rightful owner."\n\nI opened the notebook and found a yellowed photo inside, our graduation photo.\n\n"Do you remember that experiment?" he suddenly asked. "The time travel experiment."\n\nMy heart raced. That experiment, we always thought it failed.\n\n"Actually, it succeeded," he said. "I\'m from ten years in the future."\n\nI stared at him in shock, not knowing what to say.\n\n"I just wanted to tell you that your theory was correct," he smiled. "But please don\'t continue researching it, or it will bring disaster."\n\nWith that, he put on his raincoat and disappeared into the night.\n\nThe next day, I saw a news article: A man was struck by lightning in the rain last night, dead on the spot. The photo showed the visitor from last night.', category_id: 13 },
  { title: 'Cafe Secret', content: 'I go to "Time" cafe every day. Not for anything else, just for the老板娘.\n\nShe always wears a vintage dress, smiling as she serves customers. Her eyes seem to hold countless stories.\n\n"A latte?" she asks, as if we\'ve known each other for a long time.\n\n"Yes." I nod.\n\nAs she turns to make the coffee, I notice a strange birthmark on her wrist, like a clock.\n\n"Do you believe time can stand still?" she suddenly asks.\n\nI pause. "Not really."\n\n"Then do you believe in miracles?" she puts the coffee in front of me.\n\n"Sometimes."\n\nShe smiles. "That\'s enough."\n\nFrom that day on, I noticed something strange: every time I\'m in the cafe, time seems to pass very slowly.\n\nOnce, I sat there for three hours, but when I came out, only ten minutes had passed.\n\nI began to suspect there was something secret about this cafe.\n\nUntil one day, I saw her packing up, getting ready to close.\n\n"Leaving?" I ask.\n\n"Yes," she nods. "Time\'s up."\n\n"What time?"\n\n"My time." She takes off her watch. "This cafe, I traded time for it. Now, I\'m going to a place without time."\n\nShe disappears behind the door. I rush out, but only see an empty space.\n\nThere was once a cafe called "Time".', category_id: 13 },
  { title: 'Old Book Memory', content: 'In an old bookstore, I found a strange book. The cover was dark brown, no title, just a golden lock pattern.\n\n"This book is special," the owner said. "It remembers everyone who reads it."\n\nI bought it half-believing.\n\nAt home, I opened the first page. It said: "Every reader of this book will become part of the book."\n\nI continued reading and found the story was actually about me.\n\nIt detailed my childhood experiences, even the details I had forgotten.\n\nI became more and more afraid as the content began to predict the future.\n\n"Tomorrow, you will meet a woman in a red coat," it said.\n\nThe next day, I really met her.\n\n"Next Wednesday, you will receive a mysterious package."\n\nNext Wednesday, the package arrived, containing an old photo of me and a man I didn\'t know.\n\nI began to fear the book, wanting to throw it away. But no matter where I threw it, it would return to my bookshelf.\n\nUntil one day, I read the last page: "When you read here, you have become part of this book. Now, it\'s your turn to write the story."\n\nI picked up a pen and began writing my story on the blank pages.\n\nFrom that day on, the book never predicted anything again, just quietly waiting for the next reader.', category_id: 13 },
  { title: 'Subway Girl', content: 'Every morning, I take the subway at the same time.\n\nI always see that girl. She always sits in the same seat, holding a book.\n\nHer profile is beautiful, with long eyelashes and eyes focused on the page.\n\nI wanted to know her, but didn\'t know how to start.\n\nOne day, the subway suddenly braked, and her book fell to the floor.\n\nI picked it up and handed it to her.\n\n"Thank you," she smiled.\n\n"What book are you reading?" I asked.\n\n"The Lie of Time," she said. "A novel about time travel."\n\n"I like that kind of book too," I said excitedly.\n\nWe started talking and found we had many common interests.\n\nFrom that day on, we chatted every day on the subway.\n\nI found she had a unique understanding of time.\n\n"Time isn\'t linear," she said. "It\'s like a river, sometimes flowing back, sometimes branching."\n\nI was deeply attracted by her ideas.\n\nOne day, she didn\'t show up.\n\nI waited for her for a week, but she didn\'t come.\n\nI began to worry and search for her everywhere.\n\nUntil one day, I saw a missing person poster on the subway wall. The photo was her.\n\nThe poster said she had been missing for five years.\n\nI was shocked. Who had I been meeting every day?\n\nJust then, I felt someone tap my shoulder.\n\n"Are you looking for me?" her voice said in my ear.\n\nI turned around and saw her smiling at me.', category_id: 13 },
  { title: 'Mirror Self', content: 'I bought an old mirror at an antique store.\n\nThe frame was black, carved with complex patterns.\n\nAfter hanging it in my bedroom, I noticed something strange: sometimes, the me in the mirror would make different movements.\n\nOnce, I was combing my hair in front of the mirror, but the me in the mirror put down the comb and started smiling.\n\nI thought I was hallucinating and didn\'t care.\n\nUntil one day, I heard the me in the mirror speak.\n\n"Hello," he said.\n\nI stepped back in fear.\n\n"Don\'t be afraid," the mirror me said. "I\'m you from another world."\n\n"Another world?" I asked.\n\n"Yes," he said. "We are connected through this mirror."\n\nWe started talking and found the two worlds were very different.\n\nIn his world, I was a writer who had published many books.\n\nIn my world, I was just an ordinary office worker.\n\n"Do you want to swap lives?" he asked.\n\nI hesitated, then nodded.\n\nWe stepped through the mirror and swapped places.\n\nIn his world, I lived the life of my dreams.\n\nBut as time passed, I began to miss my original life.\n\nWhen I wanted to go back, I found the mirror was gone.\n\nI started searching in that world until one day, I saw the mirror in an antique store.\n\nI rushed over eagerly, but found the person in the mirror was myself.', category_id: 13 },
  { title: 'Rainy Promise', content: 'It was a rainy day. I was hiding from the rain in the library.\n\nShe sat across from me, also reading.\n\n"You didn\'t bring an umbrella either?" I asked.\n\nShe looked up and smiled. "No, it seems we\'re both trapped by the rain."\n\nWe started talking and found we were both literature lovers.\n\nAfter the rain stopped, we walked out of the library together.\n\n"Will it rain tomorrow?" she asked.\n\n"The weather forecast says it will," I replied.\n\n"Then let\'s meet here tomorrow and continue our chat," she suggested.\n\n"Okay," I agreed.\n\nThe next day, it did rain. I arrived at the library on time, but she wasn\'t there.\n\nI waited for three hours, but she didn\'t come.\n\nI thought she had forgotten or something had come up.\n\nBut every rainy day after that, I would go to the library to wait for her.\n\nA year later, I saw a note on the library bulletin board:\n\n"I\'m sorry I can\'t come. I have a rare disease and have gone to another world. But I will be with you every rainy day."\n\nIt was signed with her name.\n\nThat night, I dreamed of her smiling at me in the rain.\n\nFrom that day on, every time it rains, I feel her by my side.', category_id: 14 },
  { title: 'Old Street Cat', content: 'There\'s a black cat on the old street, always squatting at the alley entrance.\n\nIts eyes are green, like two emeralds.\n\nI pass by there every day on my way to work. It always looks at me, as if it knows me.\n\nOne day, I squatted down and touched its head.\n\nIt didn\'t run away, instead rubbing against my hand.\n\n"What\'s your name?" I asked.\n\nIt meowed, as if answering.\n\nFrom that day on, it would wait for me at the alley entrance every day.\n\nI would bring it some cat food, and it would roll at my feet.\n\nOnce, I worked late and came home to find it still waiting at the alley entrance.\n\n"Have you been waiting for me?" I asked.\n\nIt stood up, walked in front of me, as if leading the way.\n\nI followed it to an abandoned warehouse.\n\nInside, there was a cardboard box with several newborn kittens.\n\n"Are these your babies?" I asked.\n\nIt meowed and rubbed against the box.\n\nI understood; it was asking for help.\n\nI took the kittens home and took good care of them.\n\nThe black cat also followed me home and became part of our family.\n\nFrom that day on, the black cat was no longer at the alley entrance, but I knew it had found its home.', category_id: 14 },
  { title: 'Balcony Flower', content: 'On my balcony, there\'s a strange flower.\n\nI bought it at the market. The old man who sold it said it was called "Memory Flower."\n\n"It remembers everyone who takes care of it," he said.\n\nI brought it home half-believing.\n\nEvery day, I water it and fertilize it.\n\nStrangely, it has a long flowering period, always blooming with purple flowers.\n\nOne day, I noticed patterns on its petals, looking like faces.\n\nI looked closely and found those faces were my deceased relatives.\n\nI was shocked, not knowing what was happening.\n\nThat night, I dreamed of those relatives smiling at me.\n\n"We\'ve always been by your side," they said.\n\nFrom that day on, I would talk to the flower every day, telling it my thoughts.\n\nDifferent patterns would appear on its petals, sometimes my childhood memories, sometimes my future dreams.\n\nOne day, I had to move. I gave the flower to my neighbor.\n\nMy neighbor told me the flower bloomed beautifully at his house, and my face appeared on its petals.\n\nI knew that flower was the bond between me and my relatives.', category_id: 14 },
  { title: 'Midnight Call', content: 'At midnight, the phone suddenly rang.\n\nI answered groggily.\n\n"Hello?"\n\n"It\'s me," a familiar voice said.\n\nI woke up instantly. It was my deceased grandmother\'s voice.\n\n"Grandma?" I asked in surprise.\n\n"Yes, child," her voice was gentle. "I just wanted to tell you I\'m fine."\n\n"Where are you?" I asked.\n\n"I\'m in a beautiful place, with many flowers and sunshine," she said. "Don\'t worry about me."\n\n"But you\'ve already..."\n\n"I know," she interrupted. "But I\'ve always been by your side. Look at the stars outside, the brightest one is me."\n\nI looked out the window. There really was a particularly bright star.\n\n"Grandma, I miss you," I cried.\n\n"I miss you too, child," she said. "But you need to live well and take care of yourself."\n\nThe phone suddenly went dead. I called back, but it was busy.\n\nFrom that day on, whenever I encounter difficulties, I look at that bright star outside the window.\n\nI know Grandma is always watching over me.', category_id: 14 },
  { title: 'Bookstore Owner', content: 'I often go to a second-hand bookstore. The owner is a kind old man.\n\nHe always sits behind the counter, wearing reading glasses, reading a thick book.\n\n"Need any help?" he always smiles when he sees me.\n\nI tell him what book I want, and he always finds it accurately.\n\nOnce, I asked him, "How long have you been working here?"\n\n"A long time," he said. "Since I was a child."\n\nI thought he was joking, because he looked only in his sixties.\n\nUntil one day, I found a photo in an old book. The person in the photo was the owner, with a young boy beside him.\n\nOn the back of the photo, it said: Summer 1950.\n\nI was shocked. That meant the owner was at least ninety years old, but he looked only in his sixties.\n\nI asked him how he did it.\n\nHe smiled. "Because books have magic. They keep people young."\n\nFrom that day on, I went to the bookstore more often, hoping to gain the same magic from books.\n\nOne day, I found the bookstore closed. There was a note on the door: "I\'ve gone to find new books. Farewell if we are destined."\n\nI never saw that owner again, but I know he must be somewhere, with books.', category_id: 14 },
  { title: 'Park Bench', content: 'There\'s an old bench in the park. I sit there every day.\n\nNames and dates are carved on the backrest, looking quite old.\n\nOne day, I found a notebook on the bench.\n\nThe cover was blue, with the words: "For the next person sitting on this bench."\n\nI opened the notebook and read a girl\'s story.\n\nShe and her boyfriend often dated on this bench. They planned their future, wanting to get married and have a family.\n\nBut later, her boyfriend got a serious illness and died.\n\nThe girl would come to this bench every day to talk to her boyfriend.\n\nThe last page said: "I\'m going far away. I hope the next person sitting on this bench can find their own happiness."\n\nI was moved by the story and decided to continue writing in the notebook.\n\nEvery day, I recorded my life and feelings in the notebook.\n\nOne day, I found the notebook had been flipped through, and there were several pages added, a boy\'s story.\n\nHe was also moved by the girl\'s story and started writing his own story in the notebook.\n\nWe communicated through the notebook, sharing our lives.\n\nUntil one day, we agreed to meet at the bench.\n\nWhen I saw him, I knew I had found my own happiness.', category_id: 14 },
  { title: 'Subway Music', content: 'Every day after work, I hear a boy playing the guitar in the subway.\n\nHe plays well, and his singing is moving.\n\nI always put some money in his guitar case and stand aside to listen.\n\nOne day, I found he wasn\'t there.\n\nI was a bit disappointed, thinking he wouldn\'t come again.\n\nBut the next day, he appeared again, looking a bit tired.\n\n"Why didn\'t you come yesterday?" I asked.\n\n"My mom is sick. I was taking care of her in the hospital," he said.\n\n"Is she okay?"\n\n"Not very good. She needs surgery," his voice choked.\n\nI took some money from my wallet and put it in his guitar case.\n\n"This is my small contribution. I hope it helps."\n\nHe looked at me gratefully. "Thank you."\n\nFrom that day on, I put more money every day.\n\nA month later, he wasn\'t there.\n\nI thought his mom\'s condition had worsened, and I was worried.\n\nBut the next day, he came, holding a bouquet of flowers.\n\n"My mom\'s surgery was successful!" he said excitedly. "This bouquet is for you."\n\nI took the flowers, my heart warm.\n\n"Thank you for your help," he said. "I\'m going to another city. My mom needs better treatment."\n\n"I wish your mom a speedy recovery," I said.\n\nHe played a song he wrote, called "Stranger\'s Warmth."\n\nI never saw him again, but his song has always stayed in my heart.', category_id: 14 },
  { title: 'Old Photo Story', content: 'While organizing my drawer, I found an old photo.\n\nIn the photo, there was a woman in a white dress, standing by the sea.\n\nShe smiled brightly, with the blue sea behind her.\n\nI didn\'t know this woman, but she felt familiar.\n\nI asked my mom. She looked at the photo and was silent for a long time.\n\n"This is your aunt," she said. "She died before you were born."\n\n"How did she die?" I asked.\n\n"She went swimming in the sea and was swept away by the waves," my mom\'s voice choked.\n\nFrom that day on, I often dreamed of this woman.\n\nIn my dreams, she always wore a white dress, stood by the sea, and waved at me.\n\nOne day, I dreamed she said to me, "Follow me."\n\nI followed her to the sea.\n\n"This is where I last saw you," she said. "I want to tell you I\'m happy now."\n\n"Are you doing well in that world?" I asked.\n\n"Very well," she smiled. "There are many people I love here."\n\n"Why do you appear in my dreams?"\n\n"Because I want to see you, my niece," she said. "You\'ve grown up and look just like me."\n\nFrom that day on, I never dreamed of her again.\n\nBut I know she\'s watching me from somewhere.', category_id: 14 },
  { title: 'Corner Breakfast Stand', content: 'Every morning, I buy a soybean milk and fried dough stick at the corner breakfast stand.\n\nThe owners are an old couple, always greeting me with a smile.\n\n"Morning, young man," the grandpa says.\n\n"Morning, grandpa," I reply.\n\n"Same as usual?" the grandma asks.\n\n"Yes, thank you."\n\nTheir breakfast is always fresh and delicious.\n\nOne day, I found the breakfast stand wasn\'t open.\n\nI thought they had something to do, so I went to another place for breakfast.\n\nBut the breakfast stand wasn\'t open for a week.\n\nI was worried and asked the neighbors.\n\n"Their son is sick and in the hospital," the neighbor said. "They went to take care of him."\n\nI felt sad.\n\nAnother week later, the breakfast stand finally opened.\n\nThe grandpa and grandma looked tired, but still smiled and greeted me.\n\n"Grandpa, grandma, how\'s your son?" I asked.\n\n"Much better, thank you for your concern," the grandpa said.\n\n"This is my small contribution," I took some money from my wallet and put it on their stand.\n\n"No, no," the grandma refused.\n\n"Take it, just consider it advance payment for breakfast."\n\nThey accepted gratefully.\n\nFrom that day on, I bought an extra breakfast every day for them to take home to their son.\n\nGradually, the old couple and I became friends.\n\nAfter their son recovered, he often came to help at the stand.\n\nThe corner breakfast stand became the place I looked forward to most every day.', category_id: 14 },
  { title: 'Library Secret', content: 'I\'m a library administrator. I work late every day.\n\nOne day, I noticed something strange: whenever I\'m alone in the library, I hear strange sounds.\n\nSometimes the sound of pages turning, sometimes someone talking.\n\nI thought it was my imagination and didn\'t care.\n\nUntil one day, while organizing the bookshelf, I found a strange book.\n\nThe cover was black, no title, just a golden lock pattern.\n\nI tried to open it, but it was locked.\n\nJust then, I heard a voice: "Do you want to know the library\'s secret?"\n\nI looked around, no one.\n\n"I\'m in the book you\'re holding," the voice said.\n\nI was scared and threw the book on the floor.\n\n"Don\'t be afraid," the voice said. "I\'m the library\'s guardian."\n\n"The library\'s guardian?" I asked.\n\n"Yes," the voice said. "Every forgotten book becomes part of the library, and I am their guardian."\n\n"Why are you talking to me?"\n\n"Because you\'re the first person to notice me," the voice said. "Your love for books has shown me your sincerity."\n\nFrom that day on, I talked to this book every day.\n\nIt told me many secrets about the library, like which book holds an ancient story, which book has a magic spell.\n\nI began to love my job even more, knowing that every book in the library has its own story.', category_id: 15 },
  { title: 'Museum Statue', content: 'In the museum, there\'s an ancient statue, said to be from ancient Greece.\n\nThe statue is called "Goddess of Time," holding an hourglass, her eyes looking forward.\n\nI go to the museum every day to see this statue, always feeling her eyes follow me.\n\nOne day, I stayed late in the museum. All other visitors had left.\n\nI stood in front of the statue and suddenly saw her eyes move.\n\nI thought I was hallucinating and rubbed my eyes.\n\n"You finally noticed me," a voice said.\n\nI looked around, no one.\n\n"I am the Goddess of Time," the voice said. "I\'ve been standing here for thousands of years."\n\n"You can talk?" I asked.\n\n"Yes," she said. "But only those who truly love art can hear my voice."\n\n"Why are you talking to me?"\n\n"Because you come to see me every day," she said. "I can feel your love for art."\n\nWe started talking. She told me many stories about ancient Greece, about her own story.\n\n"I am the guardian of time," she said. "I have witnessed countless dynasties rise and fall, countless partings."\n\n"Do you ever feel lonely?" I asked.\n\n"Sometimes," she said. "But seeing people like you makes me feel欣慰."\n\nFrom that day on, I went to the museum every day to talk to her.\n\nUntil one day, the museum closed for renovation, and the statue was moved away.\n\nI never saw her again, but I know she must be somewhere, continuing to guard time.', category_id: 15 },
  { title: 'Antique Shop Clock', content: 'In the corner of an antique shop, there\'s an old mantel clock.\n\nThe clock face is a bit斑驳, but it still keeps time accurately.\n\nI was attracted by its simplicity and decided to buy it.\n\nAt home, I put the clock on the living room table.\n\nEvery day, it chimes on time, the sound clear and melodious.\n\nOne day, I found the clock\'s hands started turning backward.\n\nI thought it was broken and planned to have it repaired.\n\nBut just then, the clock suddenly spoke: "Don\'t be afraid, I\'m just reminiscing about the past."\n\nI was shocked, thinking I heard wrong.\n\n"Yes, I can talk," the clock said. "I\'ve lived for hundreds of years and seen many things."\n\n"How did you survive?" I asked.\n\n"Because I am a witness of time," the clock said. "Every person who owned me left a trace in my memory."\n\nIt began to tell me its stories, about its former owners, about the events that happened around it.\n\nSometimes, it would turn its hands backward, taking me back to the past, showing me scenes that had disappeared.\n\nI began to like this clock, it became my best friend.\n\nUntil one day, the clock\'s hands stopped moving.\n\n"My time is up," it said. "Thank you for spending this time with me."\n\nI looked at it sadly, knowing it had completed its mission.\n\nBut I know its memories will always stay in my heart.', category_id: 15 },
  { title: 'Painter\'s Secret', content: 'I\'m a painter. I paint in my studio every day.\n\nOne day, while organizing my painting tools, I found an old palette.\n\nThe palette\'s surface was a bit worn, but still usable.\n\nI picked it up and started mixing colors.\n\nStrangely, I found the colors mixed with this palette were more vibrant and lifelike than usual.\n\nI began to paint with it, and my works were praised by many.\n\nOne day, I dreamed of an old man.\n\n"Hello," the old man said. "You\'re using my palette."\n\n"Your palette?" I asked.\n\n"Yes," the old man said. "I was a painter who died hundreds of years ago."\n\n"Why are you appearing in my dream?"\n\n"Because you\'re the first person who can make my palette发挥 its true power," the old man said. "This palette has magic. It allows painters to paint their innermost true emotions."\n\n"What do you want me to do with it?"\n\n"Use it to create more beautiful works," the old man said. "Make the world more beautiful."\n\nFrom that day on, I painted more carefully, using this palette to create many touching works.\n\nWhenever I painted, I felt the old man beside me, guiding me.\n\nI know this palette is a gift the old man left to the world.', category_id: 15 },
  { title: 'Poet\'s Notebook', content: 'In a second-hand bookstore, I found a poet\'s notebook.\n\nThe cover was brown, with the words: "My poems, my soul."\n\nI opened the notebook and read the poems, each full of emotion.\n\nFrom the content, the poet had experienced many hardships, but still held hope for life.\n\nI was deeply moved by these poems and decided to buy the book.\n\nAt home, I read a few poems every day, gaining strength from them.\n\nOne day, I found a line on the last page: "If you read this far, it means we are destined. I hope my poems can bring you some comfort."\n\nI was touched by these words and decided to continue writing in the notebook, writing my own poems.\n\nEvery day, I wrote a poem in the notebook, recording my life and feelings.\n\nStrangely, whenever I wrote poems, I felt someone beside me, guiding me.\n\nMy poems began to attract attention, and publishers contacted me to publish my collection.\n\nI know all this is thanks to that poet, thanks to his notebook.\n\nIn the preface of my collection, I wrote: "This book is completed by me and a poet I never met. His poems gave me strength, and my poems continue his dream."', category_id: 15 },
  { title: 'Musician\'s Violin', content: 'At an auction, I bought an old violin.\n\nThe violin\'s body was a bit worn, but still had a charming luster.\n\nAccording to the auctioneer, this violin once belonged to a famous musician who donated it to charity before his death.\n\nI picked up the violin and tried playing it. The sound was beautiful and deep.\n\nFrom that day on, I played the violin every day, as if guided by some force.\n\nOne day, I dreamed of that musician.\n\n"Hello," he said. "You\'re playing my violin."\n\n"Yes," I said. "It sounds beautiful."\n\n"Thank you," he said. "I\'m glad it found someone who understands it."\n\n"Can you teach me to play?" I asked.\n\n"Of course," he said. "I\'ll teach you in your dreams."\n\nFrom that day on, I learned from him in my dreams every day.\n\nMy playing improved quickly, and soon I held my own concert.\n\nAt the concert, I played his most famous piece.\n\nWhen I finished the last note, I seemed to see him smiling and clapping in the audience.\n\nI know his soul has merged with this violin.', category_id: 15 },
  { title: 'Architect\'s Drawings', content: 'At an old book stall, I found a set of ancient architectural drawings.\n\nThe paper was yellowed, but the lines were still clear.\n\nFrom the drawings, it was a magnificent palace with exquisite design.\n\nI was deeply attracted by these drawings and decided to buy them.\n\nAt home, I studied these drawings carefully and found their design concept was very advanced, even surpassing modern architecture.\n\nOne day, I dreamed of an architect.\n\n"Hello," he said. "You\'re looking at my drawings."\n\n"Yes," I said. "They\'re exquisitely designed."\n\n"Thank you," he said. "This is my life\'s work."\n\n"Why weren\'t these drawings built?" I asked.\n\n"Because the technology at that time couldn\'t realize my design," he said. "But I believe one day, someone will realize it."\n\n"I\'ll try," I said. "I\'ll become an architect and realize your dream."\n\nFrom that day on, I studied architecture more diligently, hoping to realize this architect\'s dream one day.\n\nYears later, I became a famous architect, designing many excellent buildings.\n\nBut I never forgot those drawings, never forgot that architect\'s dream.\n\nI know one day, I will realize it.', category_id: 15 },
  { title: 'Photographer\'s Camera', content: 'In an antique shop, I found an old camera.\n\nThe camera body was made of copper, a bit oxidized, but still usable.\n\nI was attracted by its simplicity and decided to buy it.\n\nAt home, I loaded film and started taking photos.\n\nStrangely, the photos taken with this camera always felt more vivid than those taken with modern cameras, as if they could capture the soul of the subject.\n\nOne day, when developing photos, I found a person I didn\'t know in the photos.\n\nThat person stood in the corner of the photo, smiling at the camera.\n\nI thought it was a developing error and redeveloped, but the person was still there.\n\nJust then, I heard a voice: "Hello, I\'m the owner of this camera."\n\nI looked around, no one.\n\n"I\'m in your camera," the voice said. "I was a photographer who died decades ago."\n\n"Why are you in my photos?" I asked.\n\n"Because I want to see the changes in this world," he said. "Thank you for using my camera to record the world."\n\nFrom that day on, I used this camera every day to record the beauty of the world.\n\nWhenever I took photos, I felt him beside me, guiding me.\n\nI know this camera is his eyes left to the world.', category_id: 15 },
  { title: 'Writer\'s Pen', content: 'At an antique market, I found an old fountain pen.\n\nThe pen body was silver, engraved with patterns, looking very exquisite.\n\nI was attracted by its appearance and decided to buy it.\n\nAt home, I started writing with it.\n\nStrangely, I found the words written with this pen were more fluent and expressive than usual.\n\nI began to write novels with it, and soon published my first book.\n\nOne day, I dreamed of a writer.\n\n"Hello," he said. "You\'re using my pen."\n\n"Yes," I said. "It helped me write many good works."\n\n"Thank you," he said. "I\'m glad it found someone who understands it."\n\n"Who are you?" I asked.\n\n"I was a writer who died decades ago," he said. "This pen was my most treasured possession."\n\n"Why does it have such magic?"\n\n"Because it carries my love for writing," he said. "I hope you can continue to use it to write more good works."\n\nFrom that day on, I wrote more carefully, using this pen to create many touching stories.\n\nWhenever I wrote, I felt him beside me, guiding me.\n\nI know this pen is a gift he left to the world.', category_id: 15 },
  { title: 'Chef\'s Recipe', content: 'At an old book stall, I found an old recipe book.\n\nThe cover was red, with the words: "My secret recipes."\n\nI opened the recipe book and found many ancient recipes, each with detailed steps.\n\nI was deeply attracted by these recipes and decided to buy the book.\n\nAt home, I started cooking according to the recipes and found the dishes were very delicious, better than any I had cooked before.\n\nOne day, I dreamed of a chef.\n\n"Hello," he said. "You\'re looking at my recipe book."\n\n"Yes," I said. "Your recipes are magical. The dishes are very delicious."\n\n"Thank you," he said. "These recipes are my life\'s work."\n\n"Who are you?" I asked.\n\n"I was a chef who died decades ago," he said. "This recipe book is my gift to future generations."\n\n"Why are these recipes so delicious?"\n\n"Because each dish contains my love," he said. "I hope you can continue to use these recipes to bring happiness to more people."\n\nFrom that day on, I cooked more carefully, using these recipes to create many delicious dishes.\n\nI opened a restaurant, using these ancient recipes to make dishes, which were welcomed by many people.\n\nI know this recipe book is a gift that chef left to the world.', category_id: 15 },
  { title: 'Traveler\'s Diary', content: 'In a second-hand bookstore, I found a traveler\'s diary.\n\nThe cover was brown, with the words: "My travels, my life."\n\nI opened the diary and read the traveler\'s experiences. From his words, I could feel his love for the world.\n\nI was deeply attracted by this diary and decided to buy it.\n\nAt home, I read a few pages every day,仿佛 experiencing his journey with him.\n\nOne day, I dreamed of this traveler.\n\n"Hello," he said. "You\'re reading my diary."\n\n"Yes," I said. "Your travels are wonderful."\n\n"Thank you," he said. "I\'m glad someone can share my travels."\n\n"Why did you write this diary?" I asked.\n\n"Because I wanted to record the beauty of this world," he said. "I hope one day, someone can see the beauty of the world through my diary."\n\n"I will," I said. "I will continue your travels and record the beauty of the world."\n\nFrom that day on, I started traveling, following the routes in the diary to many places.\n\nI also started writing my own diary, recording my travel experiences.\n\nWhenever I traveled, I felt him beside me, accompanying me.\n\nI know this diary is a gift he left to the world.', category_id: 15 },
  { title: 'Scientist\'s Notebook', content: 'At an antique market, I found a scientist\'s notebook.\n\nThe cover was blue, with the words: "My research, my dream."\n\nI opened the notebook and found many scientific research notes. Although I couldn\'t understand some of the content, I could feel the scientist\'s rigor and persistence.\n\nI was deeply attracted by this notebook and decided to buy it.\n\nAt home, I studied the content carefully and found some research on new energy that was very valuable.\n\nOne day, I dreamed of this scientist.\n\n"Hello," he said. "You\'re looking at my notebook."\n\n"Yes," I said. "Your research is very valuable."\n\n"Thank you," he said. "This is my life\'s work."\n\n"Why wasn\'t this research published?" I asked.\n\n"Because the technology at that time couldn\'t realize my ideas," he said. "But I believe one day, someone will realize it."\n\n"I\'ll try," I said. "I\'ll become a scientist and realize your dream."\n\nFrom that day on, I studied science more diligently, hoping to realize this scientist\'s dream one day.\n\nYears later, I became a famous scientist and developed a new type of new energy.\n\nIn the beginning of my research report, I wrote: "This research is completed by me and a scientist I never met. His research gave me inspiration, and my research continues his dream."', category_id: 15 },
  { title: 'Dancer\'s Shoes', content: 'In an antique shop, I found a pair of old dance shoes.\n\nThe shoes were made of satin, a bit worn, but still beautiful.\n\nI was attracted by their exquisiteness and decided to buy them.\n\nAt home, I tried them on and found they fit perfectly, as if tailored for me.\n\nI started dancing and found my movements were more graceful and fluid than usual.\n\nOne day, I dreamed of a dancer.\n\n"Hello," she said. "You\'re wearing my dance shoes."\n"Yes," I said. "They fit perfectly."\n\n"Thank you," she said. "I\'m glad they found someone who understands them."\n\n"Who are you?" I asked.\n\n"I was a dancer who died decades ago," she said. "These dance shoes were my most treasured possession."\n\n"Why do they have such magic?"\n\n"Because they carry my love for dance," she said. "I hope you can continue to use them to dance more beautiful dances."\n\nFrom that day on, I danced more carefully, using these shoes to perform many beautiful dances.\n\nI participated in many dance competitions and won many awards.\n\nWhenever I danced, I felt her beside me, guiding me.\n\nI know these dance shoes are a gift she left to the world.', category_id: 15 },
  { title: 'Gardener\'s Seeds', content: 'At a flower market, I found a packet of old seeds.\n\nThe packaging paper was yellowed, with the words: "Seeds of hope."\n\nI was attracted by the name and decided to buy them.\n\nAt home, I planted the seeds in the garden and watered and fertilized them every day.\n\nStrangely, these seeds germinated quickly and grew rapidly, soon blooming beautiful flowers.\n\nThese flowers were very colorful and fragrant, attracting many bees and butterflies.\n\nOne day, I dreamed of a gardener.\n\n"Hello," he said. "You\'re planting my seeds."\n\n"Yes," I said. "They bloom beautifully."\n\n"Thank you," he said. "These seeds are my life\'s work."\n\n"Who are you?" I asked.\n\n"I was a gardener who died decades ago," he said. "These seeds are my gift to future generations."\n\n"Why are these seeds so magical?"\n\n"Because each seed contains my love," he said. "I hope you can continue to use these seeds to bring more beauty to the world."\n\nFrom that day on, I took better care of these flowers, using their seeds to grow more flowers.\n\nMy garden became more and more beautiful, attracting many people to visit.\n\nI know these seeds are a gift that gardener left to the world.', category_id: 15 },
  { title: 'Night Bookstore', content: 'I like to visit bookstores at night because there are few people and it\'s quiet.\n\nOne day, I found a bookstore I had never seen before. Its name was "Midnight Bookstore."\n\nThe door was made of wood, with an old copper bell hanging on it.\n\nI pushed the door open, and the bell made a clear sound.\n\nThe bookstore was dim, with only a few table lamps emitting soft light.\n\nThe bookshelves were full of various ancient books, some with yellowed covers.\n\n"Welcome to Midnight Bookstore," a voice said.\n\nI turned around and saw an old man in a black robe standing behind the counter.\n\n"Do you have any special books here?" I asked.\n\n"Yes," the old man said. "There are many books about dreams here."\n\nHe handed me a black-covered book with the words: "World of Dreams."\n\nI opened the book and found the content was strange, like someone\'s dream records.\n\n"This book can help you realize your dreams," the old man said. "As long as you write your dream in the book, it will come true."\n\nI half-believingly wrote my dream in the book: to become a writer.\n\nA few months later, my first book was published.\n\nI went back to the Midnight Bookstore to thank the old man.\n\nBut the bookstore was gone, replaced by an empty lot.\n\nI know that old man was the guardian of dreams.', category_id: 16 },
  { title: 'Rainy Bookstore', content: 'On a rainy day, I found a bookstore hidden in an alley.\n\nThe door was green, with a small sign: "Raindrop Bookstore."\n\nI pushed the door open. Inside was warm and comfortable, filled with the aroma of coffee.\n\nThe bookshelves were full of various books, and there were some rain paintings on the walls.\n\n"Welcome," a girl said with a smile. "You\'re the first customer today."\n\n"The environment here is nice," I said. "Why is it called Raindrop Bookstore?"\n\n"Because I like rain," the girl said. "Rainy days are the best for reading."\n\nI picked a book from the shelf and sat by the window, drinking coffee and reading.\n\nThe rain outside got heavier, but I felt calm.\n\n"Do you like this book?" the girl asked.\n\n"Yes," I said. "It\'s well written."\n\n"I wrote that book," the girl said. "It\'s my first book."\n\n"Really?" I asked in surprise. "It\'s wonderful."\n\n"Thank you," the girl said. "I hope my book can bring some warmth to people."\n\nFrom that day on, I often went to Raindrop Bookstore, chatting with the girl and sharing reading experiences.\n\nWe became friends, and I also started trying to write.\n\nOne day, I found the bookstore closed. There was a note on the door: "I\'ve gone to find new inspiration. Farewell if we are destined."\n\nI know she must be somewhere, continuing her writing dream.', category_id: 16 },
  { title: 'Old Object Story', content: 'I like collecting old objects because each old object has its own story.\n\nOne day, I found an old wallet at a flea market.\n\nThe wallet was brown, a bit worn, with an old photo inside showing a young couple.\n\nI bought the wallet and decided to find its owner.\n\nI found a business card in the wallet with an address.\n\nI followed the address and found an elderly woman.\n\n"Is this your wallet?" I asked.\n\nShe took the wallet, looked at it carefully, and her eyes watered.\n\n"Yes," she said. "This was my husband\'s wallet. He died ten years ago."\n\n"Is this photo of you two?" I asked.\n\n"Yes," she said. "This is our wedding photo."\n\nShe told me the story of her and her husband, how they met, fell in love, and spent a beautiful life together.\n\n"Thank you," she said. "This wallet is my most precious possession."\n\nFrom that day on, I cherished every old object I collected more, knowing they all carry their owners\' memories and emotions.\n\nI started writing a book about old object stories, hoping to let people feel the beauty of life through these stories.', category_id: 16 },
  { title: 'Starlight Promise', content: 'On a clear night, I went stargazing with my friend.\n\nWe lay on the grass, looking up at the stars, talking about our dreams.\n\n"I want to be an astronaut," my friend said. "To explore the mysteries of the universe."\n\n"I want to be a writer," I said. "To write my own stories."\n\n"Let\'s make a promise," my friend said. "Let\'s meet here in ten years and see if our dreams have come true."\n\n"Okay," I agreed.\n\nTen years later, I came to the place as promised.\n\nMy friend didn\'t come, but I saw a particularly bright star.\n\nI know that was my friend watching me.\n\nLater, I learned from my friend\'s family that he had died in a space training accident.\n\nBut I believe his soul has become a star, exploring the mysteries of the universe.\n\nFrom that day on, whenever I encounter difficulties, I look up at the stars, searching for that brightest one.\n\nI know my friend is always watching me, encouraging me.\n\nI have also been working hard, hoping to fulfill our promise.', category_id: 16 },
  { title: 'Time\'s Gift', content: 'In an antique shop, I found an old hourglass.\n\nThe glass was a bit cloudy, but it still timed accurately.\n\nI was attracted by its simplicity and decided to buy it.\n\nAt home, I put the hourglass on the table, watching the sand fall grain by grain.\n\nStrangely, whenever I watched the hourglass, I felt time slow down.\n\nOne day, I dreamed of an old man.\n\n"Hello," the old man said. "You\'re looking at my hourglass."\n\n"Yes," I said. "It\'s special."\n\n"Thank you," the old man said. "This hourglass is a gift from time."\n\n"What do you mean?" I asked.\n\n"It lets you see the preciousness of time," the old man said. "It makes you cherish every minute and second."\n\nFrom that day on, I cherished time more, living each day to the fullest.\n\nI started learning new skills, making new friends, and doing meaningful things.\n\nMy life became more fulfilling and meaningful.\n\nI know this hourglass is a gift time gave me.', category_id: 16 },
  { title: 'Memory Fragments', content: 'I have a habit of collecting small fragments of life, like movie tickets, bus tickets, postcards, etc.\n\nThese fragments record the little moments of my life. Whenever I see them, I remember the scenes at that time.\n\nOne day, while organizing these fragments, I found an old photo.\n\nIn the photo, there was me and a girl, standing by the sea, smiling happily.\n\nI didn\'t remember this girl, but she felt familiar.\n\nI tried to recall and finally remembered she was my elementary school deskmate. We were best friends.\n\nLater, she transferred schools because of her family, and we lost contact.\n\nI decided to find her, and through various means, finally found her contact information.\n\nWhen we met, we had both grown up, but our memories were still clear.\n\n"Do you still keep this photo?" she asked.\n\n"Yes," I said. "It\'s my most precious memory."\n\nWe talked about the past, as if we were back in childhood.\n\nFrom that day on, we became friends again, meeting often and sharing our lives.\n\nI know those memory fragments are my most precious wealth.', category_id: 16 },
  { title: 'Wings of Dreams', content: 'I dreamed of becoming a pilot since I was a child, able to fly freely in the blue sky.\n\nBut due to family reasons, I didn\'t have the opportunity to realize this dream.\n\nI could only imagine myself flying a plane in the blue sky in my dreams.\n\nOne day, I found a model airplane at an antique market.\n\nThe model\'s wings were a bit damaged, but still exquisite.\n\nI bought the model and put it in my study.\n\nWhenever I saw it, I thought of my dream.\n\nOne day, I dreamed of a pilot.\n\n"Hello," he said. "You really want to be a pilot?"\n\n"Yes," I said. "But I don\'t have the opportunity."\n\n"Opportunities are created by yourself," he said. "As long as you have a dream, you can definitely realize it."\n\nFrom that day on, I studied harder, hoping to realize my dream one day.\n\nAfter years of hard work, I finally became a pilot, able to fly freely in the blue sky.\n\nWhenever I fly a plane, I think of that model airplane, of the pilot\'s words.\n\nI know the wings of dreams have always been in my heart.', category_id: 16 },
  { title: 'Power of Friendship', content: 'Xiao Ming and I were good friends since childhood. We once promised to see the world together.\n\nBut as we grew up, we were busy with our own lives and contact became less and less.\n\nOne day, I received a letter from Xiao Ming. He said he was seriously ill and in the hospital.\n\nI immediately went to the hospital and saw Xiao Ming lying in bed, his face pale.\n\n"You came," he smiled. "I knew you would come."\n\n"You will get better," I said. "We still need to see the world together."\n\nXiao Ming smiled. "I know, with you here, I will definitely get better."\n\nFrom that day on, I went to the hospital every day to accompany Xiao Ming, telling him stories from outside and encouraging him.\n\nWith my encouragement, Xiao Ming\'s condition gradually improved.\n\nA few months later, Xiao Ming was discharged from the hospital.\n\nWe fulfilled our promise and went to see the world together.\n\nI know the power of friendship is the most powerful force in the world.', category_id: 16 },
  { title: 'The Face of Love', content: 'Xiao Hong and I met in college. We fell in love at first sight and soon fell deeply in love.\n\nAfter graduation, we got married and started our life together.\n\nBut life isn\'t always smooth. We also quarreled over small things.\n\nOne day, we had a big fight over a small matter, and Xiao Hong ran out angrily.\n\nAfter calming down, I started looking for Xiao Hong.\n\nI found her at the place where we first met. She was sitting there, looking into the distance.\n\n"I\'m sorry," I said. "I shouldn\'t have quarreled with you."\n\nXiao Hong turned around and looked at me. "I was also at fault."\n\nWe sat down and talked about our past, about our future.\n\n"Do you know why I chose to be with you?" Xiao Hong asked.\n\n"Why?" I asked.\n\n"Because you always appear when I need you," Xiao Hong said. "Because you always understand me."\n\nI hugged Xiao Hong movedly. "I will always be by your side, no matter what happens."\n\nFrom that day on, we cherished each other more, understood each other more.\n\nI know the face of love is two people understanding each other, supporting each other, walking through every stage of life together.', category_id: 16 },
  { title: 'The Meaning of Life', content: 'I\'m a doctor. I contact many patients every day, seeing many partings.\n\nOne day, I met a young girl with a terminal illness, only a few months left to live.\n\nBut she was optimistic, always smiling at life.\n\n"Aren\'t you afraid?" I asked her.\n\n"I am, but I cherish every moment now more," she said. "I want to do meaningful things in the limited time."\n\nShe started keeping a diary, recording her life and feelings.\n\nShe also started helping other patients, encouraging them, giving them hope.\n\nA few months later, the girl died, but her diary was published, helping many people.\n\nI read her diary, and there was a sentence that impressed me deeply: "The meaning of life is not its length, but its width."\n\nFrom that day on, I cherished my work more, cared more about my patients.\n\nI know the meaning of life is to do meaningful things in limited time, bringing some beauty to the world.', category_id: 16 },
  { title: 'Light of Hope', content: 'On a cold winter day, I met a homeless old man.\n\nHe was wearing tattered clothes, huddled in a corner, shivering.\n\nI gave him some money. He looked at me gratefully. "Thank you, young man."\n\n"Why are you here?" I asked.\n\n"I lost everything," he said. "No home, no family."\n\n"Do you still have hope?" I asked.\n\n"Yes," he said. "As long as there is hope, there is the courage to live."\n\nHe told me his story. He once had a happy family, but a fire took everything.\n\nBut he didn\'t give up, always looking for new hope.\n\n"What is hope?" I asked.\n\n"Hope is a beam of light in the dark," he said. "A fire in the cold, a glimmer of life in despair."\n\nFrom that day on, I paid more attention to those in need, giving them hope and warmth.\n\nI know the light of hope is the warmest light in the world.', category_id: 16 },
  { title: 'Power of Bravery', content: 'I was very timid since childhood, afraid of many things, like darkness, heights, strangers.\n\nBut I knew I had to become brave, otherwise I couldn\'t face the challenges of life.\n\nOne day, I decided to challenge myself, doing things I was afraid of.\n\nI went to an amusement park and rode a roller coaster; I went to a cinema and watched a horror movie; I went to a strange place and talked to strangers.\n\nAt first, I was very afraid, but as time passed, I gradually overcame my fear.\n\nI found that bravery is not the absence of fear, but choosing to move forward despite fear.\n\nOne day, I encountered someone being bullied by a group of people.\n\nI didn\'t hesitate, stepped forward, and helped him.\n\nAlthough I was afraid, I knew it was the right thing to do.\n\nFrom that day on, I became braver and more confident.\n\nI know the power of bravery is the most powerful force in the world.', category_id: 16 },
  { title: 'Reward of Kindness', content: 'I\'m an ordinary office worker. I take the bus to work every day.\n\nOne day, I saw an old man on the bus who had no seat and could only stand.\n\nI offered my seat to him. He thanked me gratefully. "Thank you, young man."\n\n"You\'re welcome," I said. "It\'s what I should do."\n\nFrom that day on, I gave up my seat to those in need every day on the bus.\n\nOne day, I forgot my wallet and couldn\'t pay the fare.\n\nJust when I was embarrassed, a girl helped me pay the fare.\n\n"Thank you," I said. "I will pay you back."\n\n"No need," the girl said. "I once received help from others, now it\'s my turn to repay."\n\nI suddenly realized that kindness is passed on.\n\nFrom that day on, I worked harder to help others, hoping to pass kindness on.\n\nI know the reward of kindness is not material, but spiritual satisfaction.', category_id: 16 },
  { title: 'Power of Persistence', content: 'I loved painting since childhood, but my painting skills were not good, often mocked by others.\n\nBut I didn\'t give up, practicing painting every day, hoping to improve my skills.\n\nOne day, I saw a painting competition online and decided to participate.\n\nI spent a month painting my most satisfied work.\n\nBut the competition results came out, and I didn\'t win.\n\nI was disappointed, but I didn\'t give up, continuing to practice painting.\n\nA few years later, I participated in that painting competition again and won the first prize.\n\nI know this is the result of my persistence.\n\nFrom that day on, I believed in the power of persistence more.\n\nI know as long as you persist, you can definitely realize your dream.', category_id: 16 },
  { title: 'Power of Tolerance', content: 'My neighbor and I had a dispute over a small matter, and our relationship became tense.\n\nOne day, I found my neighbor\'s garden flowers were damaged. I thought it was done by his enemy.\n\nBut later I found it was done by my dog.\n\nI felt guilty and took the initiative to apologize to my neighbor.\n\n"It\'s okay," my neighbor said. "It\'s just some flowers. I can plant them again."\n\nHis tolerance moved me, and our relationship improved.\n\nFrom that day on, I learned to be more tolerant, to understand others.\n\nI know the power of tolerance is the greatest power in the world.', category_id: 16 },
  { title: 'Power of Gratitude', content: 'I used to be a very selfish person, only caring about myself, not others.\n\nBut one day, I met an old man who taught me gratitude.\n\n"Do you know what you have now?" the old man asked.\n\n"I have a job, a family, some friends," I said.\n\n"Do you feel grateful?" the old man asked.\n\nI was stunned. I had never thought about this question.\n\n"Gratitude is a power," the old man said. "It makes you cherish what you have more, makes you happier."\n\nFrom that day on, I wrote down three things I was grateful for every day.\n\nI was grateful for my family, my friends, my job, every beautiful moment in life.\n\nMy life became happier and more fulfilling.\n\nI know the power of gratitude is the most beautiful power in the world.', category_id: 16 },
  { title: 'Starting Point of Dreams', content: 'I\'m an ordinary college student, living a ordinary life every day.\n\nBut I have a dream: to become a writer, to write my own stories.\n\nI started writing novels, writing a little every day, although they weren\'t good, I didn\'t give up.\n\nOne day, I submitted my novel to a publisher, hoping to be published.\n\nA few months later, I received a reply from the publisher. They said my novel had potential and were willing to publish it.\n\nI was so moved that I cried. This was the starting point of my dream.\n\nFrom that day on, I worked harder to write, hoping to write more good works.\n\nI know the starting point of dreams is at your feet, as long as you are willing to take the first step.', category_id: 16 },
  { title: 'Miracle of Life', content: 'I\'m a nurse. I take care of many patients every day.\n\nOne day, I met a premature baby who was only two pounds, critical condition.\n\nThe doctor said his survival rate was very low, but we didn\'t give up, continuing to try our best to save him.\n\nAfter several months of treatment, the premature baby was finally discharged, growing healthily.\n\nI saw his parents holding him, their faces full of happy smiles, and I also felt happy.\n\nI know this is a miracle of life.\n\nFrom that day on, I cherished my work more, cared more about my patients.\n\nI know the miracle of life is in our efforts.', category_id: 16 },
  { title: 'Seed of Hope', content: 'On a barren land, I planted a seed.\n\nI watered and fertilized it every day, hoping it would germinate.\n\nBut several months passed, and the seed still didn\'t germinate.\n\nI thought it was dead and stopped caring for it.\n\nBut one spring morning, I found a small sprout emerging from the ground.\n\nI was surprised and happy, continuing to care for it.\n\nA few months later, it grew into a big tree, blooming many beautiful flowers.\n\nI know this is a seed of hope. As long as you don\'t give up, it will germinate and grow.\n\nFrom that day on, I believed in the power of hope more.\n\nI know the seed of hope is in our hearts. As long as you water it with care, it will grow into a towering tree.', category_id: 16 }
];

async function publishArticles() {
  let count = 0;
  for (const article of articles) {
    count++;
    try {
      const response = await axios.post('http://localhost:3000/api/articles', article, {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });
      console.log(`Article ${count}: ${response.status}`);
    } catch (error) {
      console.log(`Article ${count} Error: ${error.message}`);
    }
    await new Promise(resolve => setTimeout(resolve, 500));
  }
  console.log(`Total articles published: ${count}`);
}

publishArticles();